-- Read-only schema/model audit. No permission changes or Sage DML.
SET NOCOUNT ON;
DECLARE @Catalog nvarchar(max)=(SELECT
 CAST(1 AS bit) AS ok,'TEST' AS folder,
 (SELECT t.name AS [table],c.name AS [column],TYPE_NAME(c.system_type_id) AS [type],c.max_length,c.precision,c.scale,c.is_identity,c.is_computed,c.is_nullable,c.default_object_id,c.generated_always_type
  FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id
  WHERE s.name='TEST' AND t.name IN ('ITMCATEG','ITMMASTER','ITMFACILIT','ITMSALES','ITMBPS','ATEXTRA') ORDER BY t.name,c.column_id FOR JSON PATH) AS columns,
 (SELECT t.name AS [table],i.name AS [index],i.is_unique,i.has_filter,i.filter_definition,c.name AS [column],ic.key_ordinal
  FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.indexes i ON i.object_id=t.object_id JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id
  WHERE s.name='TEST' AND i.is_unique=1 AND ic.key_ordinal>0 AND t.name IN ('ITMCATEG','ITMMASTER','ITMFACILIT','ITMSALES','ITMBPS','ATEXTRA') FOR JSON PATH) AS unique_indexes,
 (SELECT name,COALESCE(HAS_PERMS_BY_NAME('TEST.'+name,'OBJECT','SELECT'),0) AS can_select,COALESCE(HAS_PERMS_BY_NAME('TEST.'+name,'OBJECT','INSERT'),0) AS can_insert
  FROM (VALUES('ITMCATEG'),('ITMMASTER'),('ITMFACILIT'),('ITMSALES'),('ITMBPS'),('ATEXTRA')) t(name) FOR JSON PATH) AS permissions,
 (SELECT c.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT c.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash
  FROM TEST.ITMCATEG c WHERE c.STOFCY_0='' OR c.TCLCOD_0=@Category FOR JSON PATH) AS categories,
 (SELECT TOP(30) m.ITMREF_0,JSON_QUERY((SELECT m.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS fields,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT m.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash
  FROM TEST.ITMMASTER m WHERE m.ITMREF_0 IN ('TESTART201','TESTART202','TESTART203','A10/40','CONTRAT_MAINTENAN','SCREW_F994') OR (m.TCLCOD_0=@Category AND (@Stock=0 OR m.STOMGTCOD_0=@Stock))
  ORDER BY CASE WHEN m.ITMREF_0 IN ('TESTART201','A10/40') THEN 0 ELSE 1 END,m.ITMREF_0 FOR JSON PATH) AS articles,
 (SELECT f.ITMREF_0,f.STOFCY_0,JSON_QUERY((SELECT f.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS fields,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT f.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash
  FROM TEST.ITMFACILIT f WHERE f.ITMREF_0 IN ('TESTART201','TESTART202','TESTART203','A10/40','CONTRAT_MAINTENAN') FOR JSON PATH) AS facilities,
 (SELECT s.ITMREF_0,JSON_QUERY((SELECT s.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS fields,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT s.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash
  FROM TEST.ITMSALES s WHERE s.ITMREF_0 IN ('TESTART201','TESTART202','A10/40') FOR JSON PATH) AS sales,
 (SELECT b.ITMREF_0,b.BPSNUM_0,JSON_QUERY((SELECT b.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS fields,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT b.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash
  FROM TEST.ITMBPS b WHERE b.ITMREF_0 IN ('SCREW_F994','TESTART201','TESTART202','A10/40') FOR JSON PATH) AS supplier_models,
 (SELECT a.IDENT1_0,a.LANGUE_0,JSON_QUERY((SELECT a.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS fields,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT a.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash
  FROM TEST.ATEXTRA a WHERE a.CODFIC_0='ITMMASTER' AND a.ZONE_0='DES1AXX' AND a.LANGUE_0='FRA' AND a.IDENT1_0 IN ('TESTART201','TESTART202') FOR JSON PATH) AS translations,
 (SELECT FCY_0,FCYNAM_0 FROM TEST.FACILITY FOR JSON PATH) AS sites,
 (SELECT UOM_0 FROM TEST.TABUNIT FOR JSON PATH) AS units,
 (SELECT * FROM TEST.GACCCODE WHERE TYP_0=1 FOR JSON PATH) AS accounting,
 (SELECT * FROM TEST.TABVAT FOR JSON PATH) AS taxes,
 (SELECT * FROM TEST.TABVACITM FOR JSON PATH) AS tax_levels,
 (SELECT * FROM TEST.TABVAC FOR JSON PATH) AS tax_determinations,
 (SELECT z.CODFIC_0,z.CODZONE_0,l.LANNUM_0,l.LANMES_0 FROM TEST.ATABZON z JOIN TEST.APLSTD l ON l.LANCHP_0=z.NOLIB_0 AND l.LAN_0='FRA' WHERE z.CODFIC_0='ITMMASTER' AND z.CODZONE_0='NEGSTO' FOR JSON PATH) AS menus,
 (SELECT BPSNUM_0,BPSNAM_0,ENAFLG_0 FROM TEST.BPSUPPLIER FOR JSON PATH) AS suppliers,
 (SELECT ITMREF_0 FROM TEST.ITMMASTER WHERE ITMREF_0=@Code FOR JSON PATH) AS existing_article
FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
SELECT @Catalog;
